/* From Uiverse.io by vinodjangid07  - Tags: simple, card, delete, hover effect, buttons */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: fit-content;
  background: rgb(255, 255, 255);
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 30px;
  position: relative;
  box-shadow: 20px 20px 30px rgba(0, 0, 0, 0.068);
}
.__UIV_SCOPE__ .card-content {
  width: 100%;
  height: fit-content;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.__UIV_SCOPE__ .card-heading {
  font-size: 20px;
  font-weight: 700;
  color: rgb(27, 27, 27);
}
.__UIV_SCOPE__ .card-description {
  font-weight: 100;
  color: rgb(102, 102, 102);
}
.__UIV_SCOPE__ .card-button-wrapper {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.__UIV_SCOPE__ .card-button {
  width: 50%;
  height: 35px;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  font-weight: 600;
}
.__UIV_SCOPE__ .primary {
  background-color: rgb(255, 114, 109);
  color: white;
}
.__UIV_SCOPE__ .primary:hover {
  background-color: rgb(255, 73, 66);
}
.__UIV_SCOPE__ .secondary {
  background-color: #ddd;
}
.__UIV_SCOPE__ .secondary:hover {
  background-color: rgb(197, 197, 197);
}
.__UIV_SCOPE__ .exit-button {
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background-color: transparent;
  position: absolute;
  top: 20px;
  right: 20px;
  cursor: pointer;
}
.__UIV_SCOPE__ .exit-button:hover svg {
  fill: black;
}
.__UIV_SCOPE__ .exit-button svg {
  fill: rgb(175, 175, 175);
}
